:root{font-family:Arial,Helvetica,sans-serif;color:#18312f;background:#f1f3eb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.preview{padding:11px 6%;font-size:11px;letter-spacing:.08em;background:#dbe4d6;display:flex;justify-content:space-between;gap:10px}.frame{max-width:1100px;margin:auto;padding:30px 52px 22px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #cbd2c5;padding-bottom:25px;gap:20px}.wordmark{font-size:27px;font-weight:900;letter-spacing:-1px}.wordmark small{display:block;font-weight:500;letter-spacing:.06em;font-size:9px;margin-top:4px}.division{font-size:12px;letter-spacing:.12em;text-transform:uppercase}.hero{display:grid;grid-template-columns:1.07fr 1fr;gap:48px;padding-top:42px}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:700;margin:0 0 17px;color:#536f56}h1{font-size:57px;line-height:1.01;letter-spacing:-3px;margin:0 0 20px}h1 span{color:#718d54}p.intro{font-size:15px;line-height:1.55;max-width:355px;margin:0 0 28px;color:#57685d}.line{height:1px;background:#cbd2c5}.steps{display:flex;gap:15px;padding-top:20px;font-size:11px;color:#53655a}.steps b{display:block;font-size:14px;margin-bottom:7px;color:#233c31}.steps>div{flex:1}.form-card{background:white;border:1px solid #d6ddd2;padding:25px 27px;box-shadow:0 10px 24px #29432b0a}.card-top{display:flex;justify-content:space-between;align-items:center;gap:10px}h2{margin:0;font-size:22px;letter-spacing:-.7px}.sample{font-size:10px;color:#527046;background:#ecf3e5;padding:6px 8px;white-space:nowrap}.hint{font-size:12px;color:#6a7669;margin:10px 0 20px;line-height:1.4}label{display:block;font-size:11px;font-weight:700;margin:14px 0 7px}input,select{width:100%;font:13px Arial;border:1px solid #c6d1c0;padding:11px 12px;background:#f8faf5;color:#233c31;border-radius:0;min-width:0}input:focus,select:focus,button:focus-visible{outline:2px solid #759654;outline-offset:2px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}button{font:700 13px Arial;cursor:pointer;width:100%;margin-top:19px;padding:15px;background:#223d31;color:white;border:0;text-align:left;display:flex;justify-content:space-between}.notice{font-size:11px;line-height:1.45;margin:11px 0 0;color:#63715e;min-height:32px}.types{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:35px}.type{border-top:2px solid #b5c5a5;padding:14px 0;display:flex;align-items:center;gap:12px}.type svg{width:54px;height:43px;flex-shrink:0;fill:none;stroke:#3e5b42;stroke-width:2;stroke-linejoin:round}.type h3{font-size:12px;margin:0 0 5px}.type p{font-size:10px;margin:0;color:#6b7969}footer{display:flex;justify-content:space-between;gap:16px;border-top:1px solid #cbd2c5;margin-top:22px;padding-top:15px;font-size:10px;line-height:1.45;color:#63715e}footer strong{color:#2c4735}a{color:inherit}@media(max-width:650px){.preview{padding:10px 20px;font-size:9px}.preview span:last-child{display:none}.frame{padding:23px 21px}.hero{grid-template-columns:1fr;gap:28px;padding-top:30px}h1{font-size:48px}.intro{max-width:100%!important}.form-card{padding:22px 20px}.types{grid-template-columns:1fr;margin-top:27px;gap:0}.type{padding:14px 0}.type h3{font-size:14px}.type p{font-size:12px}.division{font-size:10px}.wordmark{font-size:24px}footer{display:block}footer>div+div{margin-top:10px}.pair{gap:10px}}@page{size:1050px 890px;margin:0}@media print{.frame{padding-top:25px}.hero{padding-top:33px}.preview{print-color-adjust:exact}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
.samplebar{padding:8px 5%;background:#e6eade;color:#475b46;display:flex;justify-content:space-between;gap:15px;font:11px Arial}.samplebar a{font-weight:bold;text-decoration:underline;color:inherit}@media(max-width:650px){.samplebar{font-size:9px}}
.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}
